Return JSON:
{"profile":{"segment_name":"","one_line_description":"who they are and what they need in one sentence","primary_job_to_be_done":"the core outcome this segment is hiring the product to achieve","secondary_jobs":["other things they use the product for"],"profile_narrative":"3-4 sentences: who this person is, their context, what drives their decisions. Written as if describing a real person to a colleague.","firmographics":{"company_size":"","industry_verticals":[],"geography":"","team_structure":""},"psychographics":{"goals":["professional goals that shape how they evaluate tools"],"fears":["what keeps them up at night — relevant to the product"],"identity":["how they see themselves professionally"]},"buying_behavior":{"decision_trigger":"what causes them to start evaluating a solution","evaluation_criteria":["what they assess when choosing"],"decision_maker":"who makes the call and who influences it","buying_timeline":"how long evaluation typically takes","budget_authority":""},"product_relationship":{"primary_use_cases":["how they use the product"],"feature_affinity":["features they use most or care about most"],"success_definition":"what does success look like for them in the product","expansion_triggers":["what causes them to upgrade or expand"],"churn_risks":["what causes them to leave or stop using"]},"messaging":{"resonate":["messages and framings that land with this segment"],"fall_flat":["messages that miss or feel off"],"their_language":["words and phrases they use that we should reflect back"]},"segment_edges":{"confused_with":"which adjacent segment is most often confused with this one","key_differentiator":"the one thing that clearly separates this segment from that adjacent one"}},"product_implications":["specific product decisions or priorities this profile suggests"],"marketing_implications":["specific channel, copy, or positioning implications"]}
